import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap-icons/font/bootstrap-icons.css";

const Home = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [comentarios, setComentarios] = useState([]);
  const [showComentarioModal, setShowComentarioModal] = useState(false);
  const [novoComentario, setNovoComentario] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchCursos = async () => {
      try {
        const response = await axios.get("http://localhost:5000/cursos");
        setCursos(response.data);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    const fetchComentarios = async () => {
      try {
        const response = await axios.get("http://localhost:5000/comentarios");
        setComentarios(response.data);
      } catch (err) {
        console.error("Erro ao carregar comentários:", err);
      }
    };

    const checkAuth = () => {
      const token = localStorage.getItem("token");
      if (token) {
        setIsAuthenticated(true);
      }
    };

    fetchCursos();
    fetchComentarios();
    checkAuth();
  }, []);

  const handleProtectedLink = (path) => {
    if (isAuthenticated) {
      navigate(path);
    } else {
      navigate("/login", { state: { from: path } });
    }
  };

  const checkAlunoAuth = () => {
    const user = JSON.parse(localStorage.getItem("user"));
    return user && user.tipo === "Aluno";
  };

  const handleComentarioClick = () => {
    if (isAuthenticated) {
      if (checkAlunoAuth()) {
        setShowComentarioModal(true);
      } else {
        alert("Apenas alunos podem deixar comentários.");
      }
    } else {
      navigate("/login", { state: { from: "/" } });
    }
  };

  const handleSubmitComentario = async () => {
    if (!novoComentario.trim()) return;

    try {
      const response = await axios.post(
        "http://localhost:5000/comentarios",
        { conteudo: novoComentario },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );

      setComentarios([response.data, ...comentarios]);
      setNovoComentario("");
      setShowComentarioModal(false);
    } catch (err) {
      console.error("Erro ao enviar comentário:", err);
      if (err.response && err.response.status === 401) {
        navigate("/login", { state: { from: "/" } });
      } else {
        alert(err.response?.data?.message || "Erro ao enviar comentário");
      }
    }
  };

  const cursosPorArea = cursos.reduce((acc, curso) => {
    if (!acc[curso.area]) {
      acc[curso.area] = [];
    }
    acc[curso.area].push(curso);
    return acc;
  }, {});

  if (loading) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="alert alert-danger">
          Erro ao carregar cursos: {error}
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid"
      style={{
        backgroundColor: "#F8F9FA",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="d-flex justify-content-end p-3">
        <a href="." className="mx-2">
          Home
        </a>
        <a href="./about" className="mx-2">
          About
        </a>
        <a href="./faq" className="mx-2">
          Faq
        </a>
        <a href="./contact" className="mx-2">
          Contacto
        </a>
        <a href="./login" className="mx-2">
          Login
        </a>
        <a href="./register" className="mx-2">
          Registo
        </a>
      </nav>
      <h1 className="text-primary mb-4">EducaWeb</h1>

      {/* Seção de Cursos */}
      <div className="row mt-4">
        {Object.entries(cursosPorArea).map(([area, cursosDaArea]) => (
          <div className="col-md-6 mb-4" key={area}>
            <div className="card h-100 border-0 shadow-sm">
              <div className="card-body">
                <h2 className="card-title text-primary">
                  {area} {getEmojiForArea(area)}
                </h2>
                <ul className="list-group list-group-flush">
                  {cursosDaArea.map((curso) => (
                    <li className="list-group-item border-start-0 border-end-0" key={curso.id}>
                      <strong>{curso.nome}</strong>
                      <div className="text-muted small mt-1">
                        {curso.periodo} | Nível {curso.nivel}
                      </div>
                      <div className="text-muted small">
                        {formatDate(curso.dataInicio)} -{" "}
                        {formatDate(curso.dataFim)}
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Seção de Testemunhos e Links */}
      <div className="row mt-5">
        <div className="col-md-6">
          <div className="bg-white p-4 rounded shadow-sm h-100">
            <div className="d-flex justify-content-between align-items-center mb-4">
              <h4 className="mb-0 text-primary">
                <i className="bi bi-chat-square-quote me-2"></i>
                Testemunhos de Alunos
              </h4>
            </div>

            {comentarios.length > 0 ? (
              <div className="testemunhos-container" style={{ maxHeight: "400px", overflowY: "auto" }}>
                {comentarios.map((comentario) => (
                  <div 
                    key={comentario.id} 
                    className="mb-4 p-3 rounded"
                    style={{
                      backgroundColor: "#f8f9fa",
                      borderLeft: "4px solid #0d6efd",
                    }}
                  >
                    <div className="d-flex align-items-center mb-2">
                      <div 
                        className="rounded-circle d-flex align-items-center justify-content-center me-3"
                        style={{
                          backgroundColor: "#0d6efd",
                          color: "white",
                          width: "40px",
                          height: "40px",
                          fontWeight: "bold",
                          fontSize: "18px"
                        }}
                      >
                        {comentario.aluno.utilizador.nome.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <h5 className="mb-0" style={{ color: "#2c3e50" }}>{comentario.aluno.utilizador.nome}</h5>
                        <small className="text-muted">
                          {new Date(comentario.dataPublicacao).toLocaleDateString("pt-PT", {
                            day: '2-digit',
                            month: 'long',
                            year: 'numeric'
                          })}
                        </small>
                      </div>
                    </div>
                    <p className="mb-0 ps-1" style={{ color: "#495057" }}>
                      "{comentario.conteudo}"
                    </p>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-4" style={{ color: "#6c757d" }}>
                <i className="bi bi-chat-left-quote" style={{ fontSize: "2rem" }}></i>
                <p className="mt-2">Seja o primeiro a deixar um testemunho!</p>
              </div>
            )}

            <button
              className="btn btn-primary mt-3 w-100 d-flex align-items-center justify-content-center"
              onClick={handleComentarioClick}
              style={{
                padding: "10px",
                borderRadius: "5px",
                fontWeight: "500"
              }}
            >
              <i className="bi bi-pencil-square me-2"></i>
              Deixar Testemunho
            </button>
          </div>
        </div>

        <div className="col-md-6">
          <div className="bg-white p-4 rounded shadow-sm h-100">
            <h4 className="text-primary mb-4">
              <i className="bi bi-box-arrow-up-right me-2"></i>
              Recursos Educacionais
            </h4>
            <div className="list-group">
              <button
                className="list-group-item list-group-item-action border-0 text-start p-3 mb-2 d-flex align-items-center"
                onClick={() => navigate("/cursos")}
                style={{
                  borderRadius: "8px",
                  backgroundColor: "#f8f9fa",
                }}
              >
                <i className="bi bi-collection me-3 fs-5 text-primary"></i>
                <div>
                  <h6 className="mb-0">Cursos</h6>
                  <small className="text-muted">Explore nossos cursos disponíveis</small>
                </div>
              </button>

              <button
                className="list-group-item list-group-item-action border-0 text-start p-3 mb-2 d-flex align-items-center"
                onClick={() => handleProtectedLink("/aulas-ao-vivo")}
                style={{
                  borderRadius: "8px",
                  backgroundColor: "#f8f9fa",
                }}
              >
                <i className="bi bi-camera-video me-3 fs-5 text-primary"></i>
                <div>
                  <h6 className="mb-0">Aulas ao Vivo</h6>
                  <small className="text-muted">Participe de aulas em tempo real</small>
                </div>
              </button>

              <button
                className="list-group-item list-group-item-action border-0 text-start p-3 mb-2 d-flex align-items-center"
                onClick={() => handleProtectedLink("/aulas-gravadas")}
                style={{
                  borderRadius: "8px",
                  backgroundColor: "#f8f9fa",
                }}
              >
                <i className="bi bi-play-circle me-3 fs-5 text-primary"></i>
                <div>
                  <h6 className="mb-0">Aulas Gravadas</h6>
                  <small className="text-muted">Assista quando quiser</small>
                </div>
              </button>

              <button
                className="list-group-item list-group-item-action border-0 text-start p-3 d-flex align-items-center"
                onClick={() => handleProtectedLink("/material")}
                style={{
                  borderRadius: "8px",
                  backgroundColor: "#f8f9fa",
                }}
              >
                <i className="bi bi-folder me-3 fs-5 text-primary"></i>
                <div>
                  <h6 className="mb-0">Material de Apoio</h6>
                  <small className="text-muted">Recursos complementares</small>
                </div>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Modal para novo comentário */}
      {showComentarioModal && (
        <div
          className="modal"
          style={{
            display: "block",
            backgroundColor: "rgba(0,0,0,0.5)",
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: 1050,
          }}
        >
          <div className="modal-dialog modal-dialog-centered">
            <div className="modal-content border-0 shadow">
              <div className="modal-header bg-primary text-white">
                <h5 className="modal-title">
                  <i className="bi bi-chat-square-quote me-2"></i>
                  Escreva seu Testemunho
                </h5>
                <button
                  type="button"
                  className="btn-close btn-close-white"
                  onClick={() => setShowComentarioModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <label htmlFor="comentarioText" className="form-label">Seu depoimento:</label>
                  <textarea
                    id="comentarioText"
                    className="form-control"
                    rows="5"
                    value={novoComentario}
                    onChange={(e) => setNovoComentario(e.target.value)}
                    placeholder="Compartilhe sua experiência com a EducaWeb..."
                    style={{ borderRadius: "5px" }}
                  ></textarea>
                </div>
              </div>
              <div className="modal-footer border-0">
                <button
                  type="button"
                  className="btn btn-outline-secondary"
                  onClick={() => setShowComentarioModal(false)}
                  style={{ borderRadius: "5px" }}
                >
                  Cancelar
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleSubmitComentario}
                  disabled={!novoComentario.trim()}
                  style={{ 
                    borderRadius: "5px",
                    padding: "8px 20px"
                  }}
                >
                  <i className="bi bi-send-fill me-2"></i>
                  Publicar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

function getEmojiForArea(area) {
  const emojis = {
    Economia: "📉",
    Programacao: "💻",
    Contabilidade: "📊",
    Ingles: "📖",
    Matematica: "🧮",
    Design: "🎨",
  };
  return emojis[area] || "📚";
}

function formatDate(dateString) {
  const options = { year: "numeric", month: "short", day: "numeric" };
  return new Date(dateString).toLocaleDateString("pt-PT", options);
}

export default Home;
